xml.Script:
        clWhite  := 'F0F0F0';
        clYellow := 'FFFF00';
        clRed    := 'FF0000';
        clBlue   := '0000FF';
        clGreen  := '008000';
        clGray   := '808080';
        clLime   := '00FF00';
        clPurple := '800080';
        clPink   := 'FF69B4';
        clGolden := 'DDBB20';
        clNavy   := '000080';
        clCyan   := '00FFFF';

        k := 0.5;

        q := 0.169022229424176; // 2*q^3+11*q^2+4*q-1=0, q=sqrt(97)/3 * sin( Pi/6 + arccos(881/(97*sqrt(97)))/3 ) - 11/6;
        r := k * sqrt(q);
        s := k * sqrt((1 - q) / q / 2);
        t := k * sqrt((1 - q) * 2);

        d1 := k * 0.528;
        d2 := k * 0.8;

        // Calcs angle from 2 to 3 while rotating over 1
        function Angle(x1, y1, z1, x2, y2, z2, x3, y3, z3);
        begin
          vx := y1 * z2 - y2 * z1;
          vy := z1 * x2 - z2 * x1;
          vz := x1 * y2 - x2 * y1;
          wx := y1 * z3 - y3 * z1;
          wy := z1 * x3 - z3 * x1;
          wz := x1 * y3 - x3 * y1;
          Result := ArcCos((vx*wx + vy*wy + vz*wz) / (vx^2 + vy^2 + vz^2));
        end;

        A1 := Angle( t, r, 0,  0,-r, t,  0,-r,-t);
        A2 := Angle( t, r, 0,  0, s, k,  0, s,-k);
        A3 := Angle( k,-s, 0,  0,-r, t,  0,-r,-t);
        A4 := Angle( k,-s, 0,  t, r, 0,  0,-r, t);
